package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Db;
import io.tenvyr.platform.Json;
import io.tenvyr.control.authority.PlanProposalService;
import io.tenvyr.control.authority.BudgetLedgerService;
import java.time.Instant;
import java.util.*;

/** Locks run before iteration; persisted hashes and unique identities own loop truth. */
public final class RuntimeCoordinationService {
    private final Db db;private final PlanProposalService plans;private final BudgetLedgerService budgets;private final RuntimeConnectionService connections;private final WorkspaceExecutionService workspaces;
    public RuntimeCoordinationService(Db db,PlanProposalService plans,BudgetLedgerService budgets,RuntimeConnectionService connections,WorkspaceExecutionService workspaces){this.db=db;this.plans=plans;this.budgets=budgets;this.connections=connections;this.workspaces=workspaces;}
    public ObjectNode startRun(String execution,JsonNode config,Instant deadline,JsonNode workspace,JsonNode evidence){return db.transaction(tx->startRun(tx,execution,config,deadline,workspace,evidence));}
    public ObjectNode startRun(Db tx,String execution,JsonNode raw,Instant deadline,JsonNode workspace,JsonNode evidence){ObjectNode config=Coordination.parseConfig(raw);assertRoles(tx,config);if(tx.one("SELECT id FROM executions WHERE id=? FOR UPDATE",execution)==null)throw fail("RUN_NOT_FOUND","Execution missing");ObjectNode existing=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",execution);if(existing!=null)return existing;return tx.insert("coordination_runs",Json.object("executionId",execution,"config",config,"workspace",workspace,"acceptanceEvidence",evidence,"phase","PLANNING","currentIterationNumber",0,"cumulativeWorkers",0,"loopDeadlineAt",deadline.toString(),"version",1));}
    public ObjectNode createNextIteration(String run){return db.transaction(tx->createNextIteration(tx,run));}
    public ObjectNode createNextIteration(Db tx,String run){ObjectNode row=lock(tx,run);if(Coordination.TERMINAL.contains(Json.text(row,"phase")))throw fail("RUN_NOT_FOUND","Run terminal");return next(tx,row);}
    private ObjectNode next(Db tx,ObjectNode run){int number=Json.integer(run,"currentIterationNumber",0)+1;ObjectNode iteration=tx.insert("coordination_iterations",Json.object("coordinationRunId",run.get("id"),"iterationNumber",number,"workerManifest",Json.array()));run.put("currentIterationNumber",number);run.set("activeIterationId",iteration.get("id"));save(tx,run);return iteration;}
    public String createPlannerStep(String runId){return db.transaction(tx->{ObjectNode run=lock(tx,runId);if(!Json.text(run,"phase").equals("PLANNING"))throw fail("RUN_NOT_FOUND","Run not planning");assertRoles(tx,run.path("config"));ObjectNode iteration=active(tx,run);String stepId="planner-"+Json.integer(run,"currentIterationNumber",0);if(Json.text(iteration,"plannerStepId","").equals(stepId))return stepId;ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",run.get("executionId"));ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",execution.get("activePlanRevisionId"));int base=revision==null?1:Json.integer(revision,"revisionNumber",1);JsonNode config=run.path("config"),planner=config.path("planner");ObjectNode input=Json.object("schemaVersion",1,"role","planner","goal",Json.text(execution.path("input"),"goal",""),"iterationNumber",run.get("currentIterationNumber"),"planRevision",base+1,"outputContract",Json.object("schema","TaskBatchProposalV1","instructions","Propose a TaskBatchProposalV1 JSON object with schemaVersion: 1, iterationNumber, baseRevision matching planRevision, tasks array, and reason. Do not modify authority fields."));if(run.hasNonNull("workspace"))input.set("workspace",run.get("workspace"));JsonNode identity=workspaces.executionWorkspaceIdentityForRun(tx,runId);if(identity!=null)input.set("executionWorkspace",identity);if(execution.path("input").hasNonNull("handoff"))input.set("handoff",HandoffService.parseBundle(execution.path("input").get("handoff")));ObjectNode step=Json.object("id",stepId,"agent",Json.text(planner,"kind").equals("connection")?Json.text(planner,"agent",Json.text(planner,"name")):Json.text(planner,"name"),"input",input,"onFailure","stop");if(Json.text(planner,"kind").equals("connection")){ObjectNode meta=Json.object("tenvyrConnectionId",planner.get("name"));if(config.path("plannerTarget").has("modelId"))meta.set("tenvyrModelId",config.path("plannerTarget").get("modelId"));step.set("metadata",meta);}ObjectNode proposal=plans.proposeWithManager(tx.connection(),Json.text(run,"executionId"),Json.object("schemaVersion",1,"baseRevision",base,"operations",Json.array(Json.object("op","addStep","step",step))),"coordinator");ObjectNode outcome=plans.activateWithManager(tx.connection(),Json.text(proposal,"id"));if(!Json.text(outcome,"decision").equals("ACCEPTED"))throw fail("RUN_NOT_FOUND","Planner activation "+Json.text(outcome,"decision"));tx.update("coordination_iterations",Json.text(iteration,"id"),Json.object("plannerStepId",stepId));return stepId;});}
    public ObjectNode submitIterationBatch(JsonNode input){ObjectNode batch=Coordination.parseBatch(input.path("proposal"));return db.transaction(tx->{ObjectNode run=lock(tx,Json.text(input,"runId"));int number=Json.integer(run,"currentIterationNumber",0);if(!Json.text(run,"phase").equals("PLANNING")||Json.integer(input,"iterationNumber",0)!=number||Json.integer(batch,"iterationNumber",0)!=number)throw fail("ITERATION_NOT_FOUND","Batch is not for active iteration");JsonNode config=run.path("config");Coordination.validateBatch(config,batch,Json.integer(run,"cumulativeWorkers",0));if(exhausted(run)){setPhase(tx,run,"LIMIT_REACHED",null);return Json.object("outcome","LIMIT_REACHED","revisionNumber",0);}assertWorkers(tx,config,batch);ObjectNode iteration=active(tx,run);ObjectNode attempt=tx.one("SELECT * FROM step_attempts WHERE id=?",input.path("plannerAttemptId"));ObjectNode planner=tx.one("SELECT * FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=?",run.get("executionId"),iteration.get("plannerStepId"));ObjectNode frozen=attempt==null||!attempt.hasNonNull("planRevisionId")?null:tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",attempt.get("planRevisionId"));if(attempt==null||planner==null||frozen==null||!Objects.equals(attempt.get("executionId"),run.get("executionId"))||!Objects.equals(attempt.get("logicalStepId"),planner.get("id"))||!Json.text(attempt,"status").equals("SUCCESS"))return failedBatch(tx,run,"PLANNER_ATTEMPT_INVALID");if(Json.integer(frozen,"revisionNumber",0)!=Json.integer(batch,"baseRevision",0))return failedBatch(tx,run,"PLANNER_BASE_REVISION_MISMATCH");ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=? FOR UPDATE",run.get("executionId"));ObjectNode activeRevision=tx.one("SELECT * FROM execution_plan_revisions WHERE id=?",execution.get("activePlanRevisionId"));if(activeRevision==null||Json.integer(activeRevision,"revisionNumber",0)!=Json.integer(batch,"baseRevision",0))return failedBatch(tx,run,"PLANNER_BASE_STALE");String proposalId=Json.text(iteration,"pendingPlanProposalId",null);if(proposalId==null){ObjectNode patch=Coordination.compilePatch(config,batch,run.get("workspace"),Json.text(execution.path("input"),"goal",""),workspaces.executionWorkspaceIdentityForRun(tx,Json.text(run,"id")));proposalId=Json.text(plans.proposeWithManager(tx.connection(),Json.text(run,"executionId"),patch,"planner"),"id");}ObjectNode activation=plans.activateWithManager(tx.connection(),proposalId);String decision=Json.text(activation,"decision");if(decision.equals("PENDING")){tx.update("coordination_iterations",Json.text(iteration,"id"),Json.object("pendingPlanProposalId",proposalId));return Json.object("outcome","PENDING","revisionNumber",0);}if(!decision.equals("ACCEPTED"))return failedBatch(tx,run,decision);ObjectNode revision=tx.one("SELECT * FROM execution_plan_revisions WHERE \"executionId\"=? ORDER BY \"revisionNumber\" DESC LIMIT 1",run.get("executionId"));ArrayNode manifest=Json.array();for(JsonNode task:batch.path("tasks")){ObjectNode logical=tx.one("SELECT id FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=?",run.get("executionId"),task.get("taskId"));if(logical==null)throw fail("RUN_NOT_FOUND","Materialized worker missing");manifest.add(Json.object("taskId",task.get("taskId"),"logicalStepId",logical.get("id"),"required",task.get("required")));}tx.update("coordination_iterations",Json.text(iteration,"id"),Json.object("plannerProposal",batch,"plannerAttemptId",input.get("plannerAttemptId"),"acceptedPlanRevisionId",revision.get("id"),"workerManifest",manifest,"verifierStepId","verify-"+number,"pendingPlanProposalId",null));run.put("cumulativeWorkers",Json.integer(run,"cumulativeWorkers",0)+batch.path("tasks").size());setPhase(tx,run,"WORKING",null);return Json.object("outcome","ACCEPTED","revisionNumber",revision.get("revisionNumber"));});}
    private ObjectNode failedBatch(Db tx,ObjectNode run,String code){setPhase(tx,run,"FAILED",code);tx.execute("UPDATE executions SET status='FAILED',\"endTime\"=now(),\"terminationReason\"=? WHERE id=? AND status='RUNNING'","Supervised team run failed: "+code,run.get("executionId"));return Json.object("outcome","FAILED","revisionNumber",0);}
    public ObjectNode consumeDecision(String runId,JsonNode raw,String attemptId){ObjectNode decision=Coordination.parseDecision(raw);String hash=Json.hash(decision);return db.transaction(tx->{ObjectNode run=lock(tx,runId),iteration=tx.one("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=? AND \"iterationNumber\"=? FOR UPDATE",runId,decision.get("iterationNumber"));if(iteration==null||!Objects.equals(iteration.get("id"),decision.get("iterationId")))throw fail("DECISION_STALE","Decision iteration identity mismatch");String phase=Json.text(run,"phase");if(iteration.hasNonNull("decisionHash"))return Json.object("outcome",Json.text(iteration,"decisionHash").equals(hash)?"idempotent":"conflict","phase",phase);if(Coordination.TERMINAL.contains(phase)||!Set.of("VERIFYING","DECIDING").contains(phase)||!Objects.equals(run.get("activeIterationId"),iteration.get("id")))return Json.object("outcome","conflict","phase",phase);if(attemptId!=null){ObjectNode verifier=tx.one("SELECT a.id FROM step_attempts a JOIN step_executions s ON s.id=a.\"logicalStepId\" WHERE a.id=? AND a.\"executionId\"=? AND s.\"stepId\"=? AND a.status='SUCCESS'",attemptId,run.get("executionId"),iteration.get("verifierStepId"));if(verifier==null)throw fail("DECISION_STALE","Verifier attempt does not own this iteration");}if(tx.execute("UPDATE coordination_iterations SET decision=?,\"decisionHash\"=?,\"verifierAttemptId\"=?,\"updatedAt\"=now() WHERE id=? AND \"decisionHash\" IS NULL",decision,hash,attemptId,iteration.get("id"))!=1)return Json.object("outcome","conflict","phase",phase);String next=switch(Json.text(decision,"action")){case "ACCEPT"->"ACCEPTED";case "FAIL"->"FAILED";case "WAIT_FOR_HUMAN"->"WAITING_FOR_HUMAN";case "CONTINUE"->{if(continuable(tx,run)){next(tx,run);yield "PLANNING";}yield "LIMIT_REACHED";}default->throw fail("DECISION_INVALID","Unknown decision");};if(Coordination.TERMINAL.contains(next))run.putNull("activeIterationId");setPhase(tx,run,next,next.equals("WAITING_FOR_HUMAN")?Json.text(decision,"reason"):null);return Json.object("outcome","consumed","phase",next);});}
    public String resolveWait(String runId,boolean approve){return db.transaction(tx->resolveWait(tx,runId,approve));}
    public String resolveWait(Db tx,String runId,boolean approve){ObjectNode run=lock(tx,runId);if(!Json.text(run,"phase").equals("WAITING_FOR_HUMAN"))throw fail("RUN_NOT_FOUND","Run not awaiting human");String phase=!approve?"FAILED":continuable(tx,run)?"PLANNING":"LIMIT_REACHED";if(phase.equals("PLANNING"))next(tx,run);else run.putNull("activeIterationId");setPhase(tx,run,phase,null);return phase;}
    public String transitionRun(String runId,String event){return db.transaction(tx->{ObjectNode run=lock(tx,runId);String phase=Coordination.transition(Json.text(run,"phase"),event);setPhase(tx,run,phase,event.equals("wait")?Json.text(run,"waitReason",null):null);return phase;});}
    public boolean reconcileCoordination(String executionId){ObjectNode run=db.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",executionId);if(run==null||Coordination.TERMINAL.contains(Json.text(run,"phase")))return false;ObjectNode execution=db.one("SELECT * FROM executions WHERE id=?",executionId);if(execution==null)return false;String status=Json.text(execution,"status"),runId=Json.text(run,"id");if(Set.of("FAILED","CANCELLED").contains(status)){transitionRun(runId,status.equals("FAILED")?"fail":"cancel");return true;}if(!status.equals("RUNNING"))return false;if(deadline(run)){transitionRun(runId,"deadline");return true;}String phase=Json.text(run,"phase");ObjectNode iteration=active(db,run);if(phase.equals("PLANNING")){String step="planner-"+Json.integer(run,"currentIterationNumber",0);ObjectNode logical=db.one("SELECT * FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=?",executionId,step);if(logical==null){createPlannerStep(runId);return true;}ObjectNode attempt=terminal(logical);if(attempt==null)return false;if(!Json.text(attempt,"status").equals("SUCCESS")){transitionRun(runId,"fail");return true;}try{ObjectNode outcome=submitIterationBatch(Json.object("runId",runId,"iterationNumber",run.get("currentIterationNumber"),"proposal",attempt.get("result"),"plannerAttemptId",attempt.get("id")));return !Json.text(outcome,"outcome").equals("PENDING");}catch(RuntimeFailure e){db.transaction(tx->failedBatch(tx,lock(tx,runId),e.code()));return true;}}if(phase.equals("WORKING")){boolean complete=true;for(JsonNode entry:iteration.path("workerManifest")){ObjectNode logical=db.one("SELECT * FROM step_executions WHERE id=?",entry.get("logicalStepId"));ObjectNode attempt=logical==null?null:terminal(logical);if(logical!=null&&Json.text(logical,"status").equals("RETRYING")){complete=false;continue;}if(attempt==null){complete=false;continue;}if(Json.bool(entry,"required",false)&&Json.text(attempt,"status").equals("FAILED")){transitionRun(runId,"fail");return true;}}if(complete){transitionRun(runId,"workersFinished");return true;}return false;}if(phase.equals("VERIFYING")){ObjectNode logical=db.one("SELECT * FROM step_executions WHERE \"executionId\"=? AND \"stepId\"=?",executionId,iteration.get("verifierStepId")),attempt=logical==null?null:terminal(logical);if(attempt==null)return false;if(!Json.text(attempt,"status").equals("SUCCESS")){transitionRun(runId,"fail");return true;}try{return Json.text(consumeDecision(runId,attempt.get("result"),Json.text(attempt,"id")),"outcome").equals("consumed");}catch(RuntimeFailure e){db.transaction(tx->failedBatch(tx,lock(tx,runId),e.code()));return true;}}return false;}
    public boolean isCompletionHeld(String execution){ObjectNode run=db.one("SELECT phase FROM coordination_runs WHERE \"executionId\"=?",execution);return run!=null&&!Coordination.TERMINAL.contains(Json.text(run,"phase"));}
    public boolean isVerifierStep(String execution,String step){return db.exists("SELECT 1 FROM coordination_iterations i JOIN coordination_runs r ON r.id=i.\"coordinationRunId\" WHERE r.\"executionId\"=? AND i.\"verifierStepId\"=?",execution,step);}
    public ObjectNode buildVerifierInput(String execution,String step){ObjectNode run=db.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",execution);if(run==null)throw fail("RUN_NOT_FOUND","Run missing");ObjectNode iteration=db.one("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=? AND \"verifierStepId\"=?",run.get("id"),step);if(iteration==null)throw fail("ITERATION_NOT_FOUND","Verifier does not own iteration");ArrayNode workers=Json.array(),omitted=Json.array();for(JsonNode entry:iteration.path("workerManifest")){ObjectNode logical=db.one("SELECT * FROM step_executions WHERE id=?",entry.get("logicalStepId")),attempt=logical==null?null:terminal(logical);ObjectNode fields=Json.object();ArrayNode refs=Json.array();if(attempt!=null&&attempt.path("result").isObject())attempt.path("result").fields().forEachRemaining(e->{if(e.getKey().equals("artifactRefs")){if(e.getValue().isArray())for(JsonNode ref:e.getValue())if(ref.isTextual()&&refs.size()<64)refs.add(ref);}else if(Json.bytes(e.getValue())>4096){fields.set(e.getKey(),Json.object("truncated",true,"bytes",Json.bytes(e.getValue())));omitted.add("worker."+Json.text(entry,"taskId")+".field."+e.getKey());}else fields.set(e.getKey(),e.getValue());});ObjectNode worker=Json.object("taskId",entry.get("taskId"),"status",attempt==null?"FAILED":Json.text(attempt,"status"),"selectedFields",fields,"artifactRefs",refs);if(attempt!=null&&attempt.hasNonNull("error"))worker.put("failureCode",Json.text(attempt,"error").substring(0,Math.min(255,Json.text(attempt,"error").length())));workers.add(worker);}ObjectNode limits=Json.object("maxIterations",run.path("config").get("maxIterations"),"maxTotalWorkers",run.path("config").get("maxTotalWorkers"),"cumulativeWorkers",run.get("cumulativeWorkers"),"remainingDeadlineMs",Math.max(0,Instant.parse(Json.text(run,"loopDeadlineAt")).toEpochMilli()-Instant.now().toEpochMilli()));if(run.path("config").has("budgetAccountId"))limits.set("remainingBudget",Json.object("accountId",run.path("config").get("budgetAccountId"),"remaining",available(run)));ObjectNode out=Json.object("schemaVersion",1,"iterationId",iteration.get("id"),"iterationNumber",iteration.get("iterationNumber"),"workers",workers,"executionStateKeys",Json.object(),"limits",limits,"evidence",Json.array(),"omitted",omitted);ObjectNode prior=db.one("SELECT decision FROM coordination_iterations WHERE \"coordinationRunId\"=? AND \"iterationNumber\"<? AND decision IS NOT NULL ORDER BY \"iterationNumber\" DESC LIMIT 1",run.get("id"),iteration.get("iterationNumber"));if(prior!=null)out.set("priorDecision",Json.object("action",prior.path("decision").get("action"),"reason",prior.path("decision").get("reason")));if(run.hasNonNull("workspace"))out.set("workspace",run.get("workspace"));Coordination.bytes(out,131072,"AGGREGATION_INVALID");return out;}
    public ObjectNode recoverRun(String execution){ObjectNode run=db.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",execution);if(run==null)throw fail("RUN_NOT_FOUND","Run missing");return Json.object("run",run,"iterations",db.query("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=? ORDER BY \"iterationNumber\" ASC",run.get("id")));}
    private ObjectNode terminal(JsonNode logical){ObjectNode attempt=db.one("SELECT * FROM step_attempts WHERE \"logicalStepId\"=? ORDER BY \"attemptNumber\" DESC LIMIT 1",logical.get("id"));return attempt!=null&&Set.of("SUCCESS","FAILED","TIMED_OUT","CANCELLED").contains(Json.text(attempt,"status"))?attempt:null;}
    private void assertRoles(Db tx,JsonNode config){for(String role:List.of("planner","verifier")){JsonNode selection=config.path(role);String executor=Json.text(selection,"kind").equals("connection")?Json.text(connections.claimRevision(tx,Json.text(selection,"name")).path("profile"),"executorId"):"agent:"+Json.text(selection,"name");if(!contains(config.path("allowedExecutors"),executor))throw fail("EXECUTOR_NOT_ALLOWED","Role executor is outside allowlist");}}
    private void assertWorkers(Db tx,JsonNode config,JsonNode batch){for(JsonNode task:batch.path("tasks")){String executor=task.has("connectionId")?Json.text(connections.claimRevision(tx,Json.text(task,"connectionId")).path("profile"),"executorId"):"agent:"+Json.text(task,"agent");if(!contains(config.path("allowedExecutors"),executor))throw fail("EXECUTOR_NOT_ALLOWED","Worker executor is outside allowlist");}}
    private static boolean contains(JsonNode array,String value){for(JsonNode n:array)if(n.asText().equals(value))return true;return false;}
    private JsonNode available(JsonNode run){try{return budgets.projection(Json.text(run.path("config"),"budgetAccountId")).path("available");}catch(Exception e){return Json.object("tokens",0,"costUsd",0,"wallTimeMs",0,"invocations",0);}}
    private boolean exhausted(JsonNode run){if(deadline(run))return true;if(!run.path("config").has("budgetAccountId"))return false;JsonNode available=available(run);if(!available.isObject()||available.isEmpty())return true;for(JsonNode amount:available)if(amount.asDouble()>0)return false;return true;}
    private static boolean deadline(JsonNode run){return Instant.now().isAfter(Instant.parse(Json.text(run,"loopDeadlineAt")));}
    private boolean continuable(Db tx,JsonNode run){if(!Coordination.continueAllowed(run.path("config"),Json.integer(run,"currentIterationNumber",0),Json.integer(run,"cumulativeWorkers",0),1)||exhausted(run))return false;try{assertRoles(tx,run.path("config"));return true;}catch(RuntimeFailure e){return false;}}
    private ObjectNode lock(Db tx,String id){ObjectNode row=tx.one("SELECT * FROM coordination_runs WHERE id=? FOR UPDATE",id);if(row==null)throw fail("RUN_NOT_FOUND","Run missing");return row;}
    private static ObjectNode active(Db tx,JsonNode run){ObjectNode iteration=tx.one("SELECT * FROM coordination_iterations WHERE id=?",run.get("activeIterationId"));if(iteration==null)throw fail("ITERATION_NOT_FOUND","Active iteration missing");return iteration;}
    private void setPhase(Db tx,ObjectNode run,String phase,String reason){run.put("phase",phase);if(reason==null)run.putNull("waitReason");else run.put("waitReason",reason);save(tx,run);if(Coordination.TERMINAL.contains(phase))workspaces.preserveExecutionWorkspaceForRun(tx,Json.text(run,"id"));}
    private static void save(Db tx,ObjectNode run){run.put("version",Json.integer(run,"version",0)+1);tx.update("coordination_runs",Json.text(run,"id"),Json.object("phase",run.get("phase"),"currentIterationNumber",run.get("currentIterationNumber"),"cumulativeWorkers",run.get("cumulativeWorkers"),"activeIterationId",run.get("activeIterationId"),"waitReason",run.get("waitReason"),"version",run.get("version"),"updatedAt",Instant.now().toString()));}
    static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
